import {jiraContext,addJiraStories,addJiraReceipt} from './testing-workbench.js';
import {jiraEvidence,jiraSite} from './jira-core.js';
const J=id=>document.getElementById(id);
const panel=document.createElement('details');panel.className='api-card jira-panel';panel.innerHTML=`<summary>Jira Cloud · import sprint stories & report bugs</summary><p id="jira-status" role="status">Checking your connection…</p><a id="jira-signin" target="_top" href="/signin-with-chatgpt?return_to=%2Ftesting-workbench.html" hidden>Sign in to ReleaseRadar to connect Jira ↗</a><div class="two"><div><label for="jira-site">Jira Cloud site URL</label><input id="jira-site" placeholder="https://your-team.atlassian.net"><label for="jira-email">Atlassian account email</label><input id="jira-email" type="email" autocomplete="username"><label for="jira-token">API token · never saved in browser storage</label><input id="jira-token" type="password" autocomplete="new-password"><label for="jira-cloud-id">Cloud ID · required for scoped API tokens</label><input id="jira-cloud-id" placeholder="Leave blank for a classic unscoped API token"><p class="fine">Use an API token, not your password. Scoped tokens need Jira read, issue-create and attachment-write scopes plus project permissions. This connection is separate from the optional Atlassian chat plugin. Credentials are encrypted on the server and private to your signed-in account. Jira Data Center is not supported.</p><div class="action-row"><button id="jira-connect">Connect Jira</button><button id="jira-disconnect">Disconnect</button></div></div><div><label for="jira-board">Scrum board</label><select id="jira-board"><option value="">Load boards first</option></select><div class="action-row"><button id="jira-boards">Load boards</button><button id="jira-more-boards" disabled>More boards</button></div><label for="jira-sprint">Sprint</label><select id="jira-sprint"><option value="">Select a board</option></select><div class="action-row"><button id="jira-sprints">Load sprints</button><button id="jira-more-sprints" disabled>More sprints</button></div><button id="jira-stories">Preview sprint issues</button></div></div><p class="fine">Preview is read-only. Select stories or other work items to import; existing local stories with the same Jira key/site are kept unchanged. Jira statuses do not automatically mark local testing Done.</p><div id="jira-issue-list"></div><div class="action-row"><button id="jira-more-stories" disabled>More sprint issues</button><button id="jira-import" disabled>Import selected issues</button></div>`;
document.querySelector('.work-grid').before(panel);
const bug=document.createElement('details');bug.className='jira-bug';bug.innerHTML=`<summary>Create a Jira bug from this session</summary><p class="fine">Select the story and session above, then prepare a draft. Nothing is sent until you review and submit it.</p><div class="two"><div><label for="jira-project">Target project key</label><input id="jira-project" maxlength="30" placeholder="PROJ"></div><div><label for="jira-type">Issue type · choose your project's Bug / Defect type</label><select id="jira-type"><option value="">Load issue types</option></select></div></div><div class="action-row"><button id="jira-types">Load issue types</button><button id="jira-more-types" disabled>More issue types</button><button id="jira-fields">Load field requirements</button></div><pre id="jira-field-info">Project-specific required fields appear here. No issue type is assumed.</pre><label for="jira-summary">Bug summary</label><input id="jira-summary" maxlength="255"><label for="jira-steps">Reproduction steps</label><textarea id="jira-steps" rows="3"></textarea><label for="jira-expected">Expected behavior</label><textarea id="jira-expected" rows="2"></textarea><label for="jira-actual">Observed behavior</label><textarea id="jira-actual" rows="2"></textarea><label for="jira-environment">Environment / build / browser</label><input id="jira-environment"><label for="jira-extra">Additional Jira fields (JSON) · use field IDs and Jira value shapes</label><textarea id="jira-extra" rows="3">{}</textarea><button id="jira-prepare">Prepare bug & evidence draft</button><label for="jira-description">Description to publish · review and edit</label><textarea id="jira-description" rows="8"></textarea><label for="jira-evidence">Evidence JSON attachment · review and redact</label><textarea id="jira-evidence" rows="8"></textarea><p class="fine">The attachment includes selected session notes, API check summaries, charter, coverage and debrief. It does not add screenshots or raw API responses automatically. Remove sensitive data before publishing to Jira.</p><label class="consent"><input type="checkbox" id="jira-confirm">I reviewed the target project, issue type, description and evidence, and want to create this Jira issue.</label><div class="action-row"><button class="primary" id="jira-create" disabled>Create bug + attach evidence</button><button id="jira-retry" disabled>Retry attachment only</button><button id="jira-check" disabled>Check submission status</button><button id="jira-new" disabled>Start a new bug draft</button></div><p id="jira-bug-status" role="status"></p><a id="jira-result-link" target="_blank" rel="noopener noreferrer" hidden>Open created Jira issue ↗</a>`;
J('save-debrief').after(bug);
let site='',boardsNext=null,sprintsNext=null,storiesNext=null,typesNext=null,issues=[],draftSession='',last=null,busy=false;
try{last=JSON.parse(sessionStorage.getItem('rr-jira-submission')||'null');}catch{}
async function call(action,input={}){const r=await fetch('/api/jira/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});const d=await r.json();if(!r.ok){const e=Error(d.error||'Jira request failed.');e.notSubmitted=d.notSubmitted===true;throw e;}return d;}
const guard=fn=>async()=>{try{await fn();}catch(e){J('jira-status').textContent=e.message;}};
async function connection(){try{const d=await call('status');site=d.site||'';J('jira-status').textContent=d.connected?'Connected to '+site:'Connect Jira to load sprint stories and create bugs.';J('jira-signin').hidden=true;J('jira-site').value=site;J('jira-disconnect').disabled=!d.connected;}catch(e){J('jira-status').textContent=e.message;J('jira-signin').hidden=!e.message.toLowerCase().includes('sign in');}}
J('jira-connect').onclick=guard(async()=>{const button=J('jira-connect');button.disabled=true;try{const d=await call('connect',{site:J('jira-site').value,email:J('jira-email').value,token:J('jira-token').value,cloudId:J('jira-cloud-id').value});J('jira-token').value='';site=d.site;issues=[];renderIssues();await connection();}finally{button.disabled=false;}});
J('jira-disconnect').onclick=guard(async()=>{await call('disconnect');site='';issues=[];renderIssues();await connection();});
function options(id,values,append=false){if(!append)J(id).replaceChildren(new Option('Choose…',''));for(const v of values)J(id).append(new Option(v.name+(v.state?' · '+v.state:''),String(v.id)));}
async function boards(more){const d=await call('boards',{startAt:more?boardsNext:0});options('jira-board',d.values,more);boardsNext=d.next;J('jira-more-boards').disabled=boardsNext===null||!d.values.length;J('jira-status').textContent='Boards loaded. Choose a board, then load its sprints.';}
async function sprints(more){const d=await call('sprints',{boardId:J('jira-board').value,startAt:more?sprintsNext:0});options('jira-sprint',d.values,more);sprintsNext=d.next;J('jira-more-sprints').disabled=sprintsNext===null||!d.values.length;J('jira-status').textContent='Sprints loaded. Choose one to preview issues.';}
J('jira-boards').onclick=guard(()=>boards(false));J('jira-more-boards').onclick=guard(()=>boards(true));J('jira-sprints').onclick=guard(()=>sprints(false));J('jira-more-sprints').onclick=guard(()=>sprints(true));J('jira-board').onchange=()=>{options('jira-sprint',[]);issues=[];renderIssues();J('jira-more-sprints').disabled=true;J('jira-more-stories').disabled=true;};J('jira-sprint').onchange=()=>{issues=[];renderIssues();J('jira-more-stories').disabled=true;};
function renderIssues(){const selected=new Set([...J('jira-issue-list').querySelectorAll('input:checked')].map(x=>x.value));J('jira-issue-list').replaceChildren();for(const i of issues){const label=document.createElement('label');label.className='jira-issue';const box=document.createElement('input');box.type='checkbox';box.value=i.key;box.checked=selected.has(i.key);const text=document.createElement('span');text.textContent=`${i.key} · ${i.fields?.issuetype?.name||'Issue'} · ${i.fields?.summary||''} (${i.fields?.status?.name||''})`;label.append(box,text);J('jira-issue-list').append(label);}J('jira-import').disabled=!issues.length;}
async function stories(more){const d=await call('stories',{sprintId:J('jira-sprint').value,cursor:more?storiesNext:''});site=d.site;if(!more)issues=[];for(const i of d.issues)if(!issues.some(x=>x.key===i.key))issues.push(i);storiesNext=d.next;renderIssues();J('jira-more-stories').disabled=!storiesNext;J('jira-status').textContent=`${issues.length} issues loaded. Select the ones you want to import.`;}
J('jira-stories').onclick=guard(()=>stories(false));J('jira-more-stories').onclick=guard(()=>stories(true));J('jira-import').onclick=guard(()=>{const selected=new Set([...J('jira-issue-list').querySelectorAll('input:checked')].map(x=>x.value));if(!selected.size)throw Error('Select at least one issue.');const result=addJiraStories(issues.filter(i=>selected.has(i.key)),site,J('jira-sprint').value);J('jira-status').textContent=`Imported ${result.added}; skipped ${result.skipped} existing issues. Local workspace capacity is 100 stories.`;});
async function types(more){const d=await call('types',{project:J('jira-project').value,startAt:more?typesNext:0});options('jira-type',d.values,more);typesNext=d.next;J('jira-more-types').disabled=typesNext===null||!d.values.length;}
J('jira-types').onclick=guard(()=>types(false));J('jira-more-types').onclick=guard(()=>types(true));J('jira-fields').onclick=guard(async()=>{const d=await call('fields',{project:J('jira-project').value,type:J('jira-type').value});J('jira-field-info').textContent=JSON.stringify(d.fields,null,2);});
const draftFields=['jira-project','jira-type','jira-summary','jira-steps','jira-expected','jira-actual','jira-environment','jira-extra','jira-description','jira-evidence'];
function buttons(){J('jira-create').disabled=busy||!!last||!draftSession||!J('jira-confirm').checked;J('jira-retry').disabled=busy||last?.phase!=='attachment_failed';J('jira-check').disabled=busy||!last;J('jira-new').disabled=busy||!last||!['complete','creation_failed'].includes(last.phase);J('jira-prepare').disabled=busy||!!last;}
for(const id of draftFields)J(id).addEventListener('input',()=>{J('jira-confirm').checked=false;buttons();});J('jira-confirm').onchange=buttons;
J('jira-prepare').onclick=guard(()=>{const c=jiraContext();if(!J('jira-steps').value.trim()||!J('jira-expected').value.trim()||!J('jira-actual').value.trim())throw Error('Describe reproduction steps, expected behavior and observed behavior first.');draftSession=c.session.id;if(!J('jira-summary').value)J('jira-summary').value=(c.session.notes.find(n=>n.kind==='Bug candidate')?.text||c.story.title).slice(0,255);if(!J('jira-project').value&&c.story.jira)J('jira-project').value=c.story.jira.key.split('-')[0];J('jira-description').value=`Environment/build: ${J('jira-environment').value||'Not recorded'}\n\nSteps to reproduce:\n${J('jira-steps').value}\n\nExpected:\n${J('jira-expected').value}\n\nObserved:\n${J('jira-actual').value}\n\nTesting context: ${c.story.title}\nCharter: ${c.session.charter}\nStory revision: ${c.session.revision} (current ${c.story.revision})\n${c.story.jira?'Source story: '+c.story.jira.site+'/browse/'+c.story.jira.key:''}\n\nAn evidence JSON file is uploaded separately; check upload status in ReleaseRadar.`;J('jira-evidence').value=JSON.stringify(jiraEvidence(c.story,c.session,c.sprint),null,2);J('jira-confirm').checked=false;buttons();J('jira-bug-status').textContent='Draft prepared. Review every field and the evidence before confirming.';});
function remember(){try{sessionStorage.setItem('rr-jira-submission',JSON.stringify(last));}catch{J('jira-bug-status').textContent='Unable to save submission recovery data. Keep this page open.';}}
function show(result){last={...last,...result};if(last.url){try{const u=new URL(last.url);jiraSite(u.origin);if(!/^\/browse\/[A-Z][A-Z0-9_]*-\d+$/i.test(u.pathname))throw Error();}catch{last.url=null;}}remember();const descriptions={complete:'Bug created and evidence attached.',attachment_failed:'Bug created, but evidence upload failed. Review the error, then retry the attachment only.',attachment_unknown:'Bug created; attachment outcome is uncertain. Inspect the issue in Jira. Do not upload again blindly.',creation_unknown:'Creation outcome is uncertain. Check Jira before creating another bug.',creating:'Creation is in progress or its outcome is uncertain. Check Jira before resubmitting.',attaching:'Attachment upload is in progress or its outcome is uncertain. Inspect Jira before retrying.',creation_failed:'Jira rejected issue creation. Correct the fields and start a new draft.'};J('jira-bug-status').textContent=(descriptions[last.phase]||last.phase)+(result.error?' '+result.error:'');J('jira-result-link').hidden=!last.url;if(last.url){J('jira-result-link').href=last.url;addJiraReceipt(last.sessionId,last);}buttons();}
J('jira-create').onclick=async()=>{if(busy||last||!J('jira-confirm').checked)return;try{const payload={requestId:crypto.randomUUID(),project:J('jira-project').value,type:J('jira-type').value,summary:J('jira-summary').value,description:J('jira-description').value,evidence:J('jira-evidence').value,extra:JSON.parse(J('jira-extra').value||'{}'),confirm:true};JSON.parse(payload.evidence);last={...payload,sessionId:draftSession,phase:'creating'};remember();busy=true;buttons();show(await call('create',payload));}catch(e){if(last)show({phase:e.notSubmitted?'creation_failed':'creation_unknown',error:e.message});else J('jira-bug-status').textContent=e.message;}finally{busy=false;buttons();}};
J('jira-retry').onclick=async()=>{if(!last||busy)return;busy=true;buttons();try{show(await call('retry-attachment',{...last,confirm:true}));}catch(e){J('jira-bug-status').textContent=e.message+' Check status before retrying.';}finally{busy=false;buttons();}};
J('jira-check').onclick=async()=>{if(!last)return;busy=true;buttons();try{show(await call('submission',{requestId:last.requestId}));}catch(e){J('jira-bug-status').textContent=e.message+' No automatic retry was attempted.';}finally{busy=false;buttons();}};
J('jira-new').onclick=()=>{if(!last||!['complete','creation_failed'].includes(last.phase))return;last=null;sessionStorage.removeItem('rr-jira-submission');draftSession='';J('jira-confirm').checked=false;J('jira-bug-status').textContent='New draft. Check existing Jira issues to avoid duplicates.';J('jira-result-link').hidden=true;buttons();};
if(last)show(last);buttons();connection();
